{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C56"],
      "claim": "Molecule 1 had an absolute oral bioavailability of 50% in humans under fasted conditions (C56), above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Molecule 2 had a high absolute oral bioavailability of 95% in healthy adult subjects after a 50 mg oral dose compared with IV (C45), well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C57"],
      "claim": "Molecule 10 had an estimated absolute oral bioavailability of 16% (95% CI 8–27%) for the suspension in immunocompromised patients aged 1–21 years (C57), below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The high-transferability evidence set is dominated by direct absolute oral bioavailability values above 20% (e.g., 50%, 95%, 38%, 50–60%, 84%). The only direct low estimate is a special-population posaconazole suspension value of 16%, and a few unspecified or qualitative low reports are outweighed by more direct measurements. Prediction: high, with moderate confidence.",
  "evidence_gaps": [
    "Posaconazole has conflicting absolute bioavailability estimates: 16% in immunocompromised pediatric/young adult patients vs 50–75% in other populations/formulations.",
    "Sorafenib has one unspecified-report estimate of ~8.5% that conflicts with multiple absolute estimates of 38–50%.",
    "Molecule 4 includes a morphine record (C10) inconsistent with the meperidine/pethidine records; discounted as a provenance conflict.",
    "Some records are qualitative or from special populations (cirrhosis, renal impairment, fed/fasted states), limiting directness."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

